import React, { forwardRef } from 'react';

const ShareCardTemplate = forwardRef(({ passenger, familyMembers }, ref) => {
  if (!passenger) return null;

  return (
    <div 
      ref={ref}
      id="share-card-template" 
      className="bg-white p-12 text-slate-900 border-[16px] border-[#8B0000] rounded-[40px] flex flex-col gap-10 font-sans"
      style={{ 
        width: '1080px', // Fixed width for predictable canvas rendering
        boxSizing: 'border-box'
      }}
    >
      {/* Header Section */}
      <div className="flex flex-col items-center justify-center border-b-4 border-[#8B0000] pb-10">
        <img 
          src="data:image/png;base64,"
          alt="जैजैपुर सेवा समिति" 
          className="w-48 h-48 object-contain mb-6"
        />
        <h1 className="text-5xl font-extrabold text-[#8B0000] mb-3 font-serif">
          7 ज्योतिर्लिंग और 1 धाम यात्रा
        </h1>
        <h2 className="text-4xl font-bold text-amber-600">
          जैजैपुर सेवा समिति
        </h2>
      </div>

      {/* Passenger Name */}
      <div className="text-center py-4 bg-amber-50 rounded-2xl border-2 border-amber-200">
        <p className="text-2xl text-slate-500 font-semibold mb-2 uppercase tracking-widest">Passenger Details</p>
        <p className="text-6xl font-black text-slate-800">{passenger.name}</p>
      </div>

      {/* Train Details */}
      {passenger.train && passenger.train.coach && passenger.train.coach !== '-' && (
        <div className="bg-slate-50 border-2 border-slate-200 rounded-2xl p-8">
          <div className="flex items-center gap-4 mb-6 border-b-2 border-slate-200 pb-4">
            <span className="text-4xl">🚆</span>
            <h3 className="text-3xl font-bold text-slate-800">Train Journey</h3>
          </div>
          
          <div className="grid grid-cols-3 gap-8">
            <div>
              <p className="text-xl text-slate-500 font-semibold mb-1 uppercase">Coach</p>
              <p className="text-4xl font-bold text-blue-700">{passenger.train.coach}</p>
            </div>
            {passenger.train.berth && passenger.train.berth !== '-' && (
              <div>
                <p className="text-xl text-slate-500 font-semibold mb-1 uppercase">Berth</p>
                <p className="text-4xl font-bold text-blue-700">{passenger.train.berth}</p>
              </div>
            )}
            {passenger.train.berthType && passenger.train.berthType !== '-' && passenger.train.berthType !== 'Unknown' && (
              <div>
                <p className="text-xl text-slate-500 font-semibold mb-1 uppercase">Berth Type</p>
                <p className="text-4xl font-bold text-blue-700">{passenger.train.berthType}</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Family Members */}
      {familyMembers && familyMembers.length > 0 && familyMembers.some(m => m.name !== passenger.name) && (
        <div className="bg-slate-50 border-2 border-slate-200 rounded-2xl p-8">
          <div className="flex items-center gap-4 mb-6 border-b-2 border-slate-200 pb-4">
            <span className="text-4xl">👨‍👩‍👧</span>
            <h3 className="text-3xl font-bold text-slate-800">Family Members</h3>
          </div>
          <div className="flex flex-col gap-8">
            {familyMembers.map((member, idx) => (
              member.name !== passenger.name && (
                <div key={idx} className="bg-white border-2 border-slate-200 rounded-xl p-6 shadow-sm">
                  <div className="flex items-center gap-3 mb-4 border-b border-slate-100 pb-3">
                    <span className="text-amber-500 text-3xl">❖</span>
                    <span className="text-3xl font-bold text-slate-800">{member.name}</span>
                  </div>
                  
                  {member.train && member.train.coach && member.train.coach !== '-' && (
                    <div className="grid grid-cols-3 gap-4 mb-4 bg-slate-50 p-4 rounded-lg">
                      <div>
                        <p className="text-sm text-slate-500 font-semibold uppercase">Coach</p>
                        <p className="text-2xl font-bold text-blue-700">{member.train.coach}</p>
                      </div>
                      {member.train.berth && member.train.berth !== '-' && (
                        <div>
                          <p className="text-sm text-slate-500 font-semibold uppercase">Berth</p>
                          <p className="text-2xl font-bold text-blue-700">{member.train.berth}</p>
                        </div>
                      )}
                      {member.train.berthType && member.train.berthType !== '-' && member.train.berthType !== 'Unknown' && (
                        <div>
                          <p className="text-sm text-slate-500 font-semibold uppercase">Berth Type</p>
                          <p className="text-2xl font-bold text-blue-700">{member.train.berthType}</p>
                        </div>
                      )}
                    </div>
                  )}

                  {member.hotels && member.hotels.length > 0 && (
                    <div className="space-y-3">
                      {member.hotels.map((hotel, hIdx) => (
                        <div key={hIdx} className="bg-amber-50 border border-amber-100 p-4 rounded-lg flex justify-between items-center">
                          <div>
                            <p className="text-sm text-slate-500 font-semibold uppercase">Hotel</p>
                            <p className="text-xl font-bold text-slate-800">{hotel.hotelName}</p>
                          </div>
                          {hotel.roomNumber && (
                            <div className="text-right">
                              <p className="text-sm text-slate-500 font-semibold uppercase">Room</p>
                              <p className="text-xl font-bold text-slate-800">{hotel.roomNumber}</p>
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )
            ))}
          </div>
        </div>
      )}

      {/* Hotel Details */}
      {passenger.hotels && passenger.hotels.length > 0 && (
        <div className="bg-slate-50 border-2 border-slate-200 rounded-2xl p-8">
          <div className="flex items-center gap-4 mb-6 border-b-2 border-slate-200 pb-4">
            <span className="text-4xl">🏨</span>
            <h3 className="text-3xl font-bold text-slate-800">Hotel Accommodation</h3>
          </div>
          
          <div className="space-y-6">
            {passenger.hotels.map((hotel, idx) => (
              <div key={idx} className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-4">
                  <span className="text-2xl font-bold text-slate-800">{hotel.hotelName}</span>
                  {hotel.day && (
                    <span className="bg-amber-100 text-amber-800 px-4 py-1 rounded-full text-xl font-bold">
                      Day {hotel.day}
                    </span>
                  )}
                </div>
                <div className="grid grid-cols-2 gap-8">
                  {hotel.floor && (
                    <div>
                      <p className="text-xl text-slate-500 font-semibold mb-1 uppercase">Floor</p>
                      <p className="text-3xl font-bold text-slate-700">{hotel.floor}</p>
                    </div>
                  )}
                  {hotel.roomNumber && (
                    <div>
                      <p className="text-xl text-slate-500 font-semibold mb-1 uppercase">Room</p>
                      <p className="text-3xl font-bold text-slate-700">{hotel.roomNumber}</p>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
      
      {/* Footer */}
      <div className="mt-auto text-center pt-8 border-t-2 border-slate-200">
        <p className="text-2xl text-slate-400 font-medium tracking-wide">
          Official Trip Document • जैजैपुर सेवा समिति
        </p>
      </div>

    </div>
  );
});

ShareCardTemplate.displayName = 'ShareCardTemplate';

export default ShareCardTemplate;
